/// <summary>
/// A location the counter confirmed empty ("Location is empty"): every line there was counted as
/// zero, and this records who verified it and when.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountEmptyLocationRow
{
    str locationId;
    str verifiedBy;
    str verifiedAtUtc;

}

Method.Source:
[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}

[DataMemberAttribute('VerifiedBy')]
public str parmVerifiedBy(str _value = verifiedBy)
{
    verifiedBy = _value;
    return verifiedBy;
}

[DataMemberAttribute('VerifiedAtUtc')]
public str parmVerifiedAtUtc(str _value = verifiedAtUtc)
{
    verifiedAtUtc = _value;
    return verifiedAtUtc;
}
